if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_action() {
    _argc_util_cache 86400 _helper_action_names fastlane-actions
}

_choice_custom_command() {
    _argc_util_comp_command
}

_choice_env() {
    _helper_env_names | _argc_util_comp_multi ,
}

_choice_lane() {
    local platform="${argc__positionals[0]}"
    [[ -n "$platform" ]] || return 0
    _helper_lanes | gawk -F'\t' -v platform="$platform" '$1 == platform { print $2 }'
}

_choice_platform() {
    _helper_lanes | gawk -F'\t' '
        $1 == "general" { print $2; next }
        !seen[$1]++ { print $1 }
    '
}

_choice_platform_name() {
    _helper_lanes | gawk -F'\t' '$1 != "general" && !seen[$1]++ { print $1 }'
}

_helper_action_names() {
    COLUMNS=9999 fastlane actions 2>/dev/null |
        _argc_util_strip_ansi |
        gawk -F'|' '
            /^\|/ {
                name = $2
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", name)
                if (name !~ /^[A-Za-z0-9_]+$/ || name == "Action") next
                description = $3
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", description)
                if (description == "") {
                    print name
                } else {
                    print name "\t" description
                }
            }
        '
}

_helper_env_names() {
    local dir file name
    for dir in fastlane .; do
        for file in "$dir"/.env.*; do
            [[ -f "$file" ]] || continue
            name="${file##*/}"
            printf '%s\n' "${name#.env.}"
        done
    done
}

_helper_lanes() {
    [[ -f fastlane/Fastfile || -f Fastfile ]] || return 0
    _argc_util_cache 300 _helper_lanes_uncached "fastlane-lanes:$PWD"
}

_helper_lanes_uncached() {
    COLUMNS=9999 fastlane lanes 2>/dev/null |
        _argc_util_strip_ansi |
        gawk '
            /^-+[^-]+-+$/ {
                section = $0
                gsub(/^-+|-+$/, "", section)
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", section)
                next
            }
            /^----- fastlane / {
                line = $0
                sub(/^----- fastlane /, "", line)
                n = split(line, parts, /[[:space:]]+/)
                if (n == 0) next
                if (section == "") section = "general"
                print section "\t" parts[n]
            }
        '
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
